INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7001, '1 Samuel 13:23', '1 Samuel', 13, 23, '&nbsp;فلستيانو د فوجيانو يوه ډله ولېږله چې د مِکماس د درې حِفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7002, '1 Samuel 14:1', '1 Samuel', 14, 1, '&nbsp;يوه ورځ يونتن هغه زلمى ته ووئيل کوم چې د هغۀ وسله وړله، ”راځه چې هغه طرف ته لاړ شُو چرته چې د فلستيانو قلعه ده.“ خو يونتن خپل پلار ساؤل خبر نۀ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7003, '1 Samuel 14:2', '1 Samuel', 14, 2, '&nbsp;ساؤل په مجرون کښې د انار د ونې لاندې ناست وو، دا جبعې ته نزدې وه او تقريباً شپږ سوه سړى د هغۀ سره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7004, '1 Samuel 14:3', '1 Samuel', 14, 3, '&nbsp;د ساؤل په سړو کښې اخياه اِمام هم وو کوم چې پېش بند ګرځولو، اخياه د يکبود د ورور اخيطوب زوئ وو، چې دے د فينحاس زوئ او د عيلى نمسے وو، چې په سيلا کښې د مالِک خُدائ اِمام وو. خو هيچا ته پته ونۀ لګېده چې يونتن تلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7005, '1 Samuel 14:4', '1 Samuel', 14, 4, '&nbsp;د مِکماس په دره کښې، چې د کومې نه يونتن تېرېدو چې فلستيانو قلعې ته ورسيږى، هلته دوه لوئې کَمَرې وې، چې د درې په دواړو طرفونو باندې يو يو وو. د يو کَمَر نوم بوصيص وو او د بل سنه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7006, '1 Samuel 14:5', '1 Samuel', 14, 5, '&nbsp;يو د درې په شمال طرف باندې وو، چې مخ يې مِکماس ته وو او بل په جنوبى طرف باندې وو چې مخ يې جبعې ته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7007, '1 Samuel 14:6', '1 Samuel', 14, 6, '&nbsp;يونتن هغه وسله وړُونکى زلمى ته ووئيل، ”راځه چې د هغه ناسنته خلقو قلعې ته ورواوړُو. کېدے شى چې مالِک خُدائ زمونږ مدد وکړى، مالِک خُدائ د ډېرو يا د لږو خلقو په ذريعه هم خلاصون ورکولے شى او داسې يو څيز هم نشته چې هغه رايسار کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7008, '1 Samuel 14:7', '1 Samuel', 14, 7, '&nbsp;زلمى ورته ووئيل، ”تۀ چې څۀ هم کول غواړې، نو په هر کار کښې زۀ درسره يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7009, '1 Samuel 14:8', '1 Samuel', 14, 8, '&nbsp;يونتن ورته ووئيل، ”ټيک ده. مونږ به هغه بل طرف ته واوړُو او پرېږده چې فلستيان مونږ ووينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7010, '1 Samuel 14:9', '1 Samuel', 14, 9, '&nbsp;کۀ هغوئ مونږ ته ووائى چې تر هغې پورې هلته ايسار شئ چې مونږ درورسېږو، نو بيا چې مونږ چرته يُو هلته به اِنتظار وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7011, '1 Samuel 14:10', '1 Samuel', 14, 10, '&nbsp;خو کۀ هغوئ مونږ ته ووائى چې راشئ، نو مونږ به ورشُو، ځکه چې دا به د هغه فتحې نښه وى چې مالِک خُدائ مونږ له په هغوئ باندې راکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7012, '1 Samuel 14:11', '1 Samuel', 14, 11, '&nbsp;نو هغوئ فلستيان پرېښودل چې هغوئ وګورى او فلستيانو ووئيل، ”ګورئ، څۀ عبرانيان د هغه غارونو نه راروان دى چې په کومو کښې پټ وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7013, '1 Samuel 14:12', '1 Samuel', 14, 12, '&nbsp;بيا هغوئ يونتن او هغه زلمى ته د کېمپ نه چغې وهلې چې، ”بره راوخېژئ، مونږ به تاسو ته چل وښايُو.“ يونتن زلمى ته ووئيل، ”ما پسې راځه. مالِک خُدائ بنى اِسرائيلو له په دوئ باندې فتح ورکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7014, '1 Samuel 14:13', '1 Samuel', 14, 13, '&nbsp;يونتن د خپلو لاسونو او پښو په ذريعه د درې نه وختلو او هغه زلمے ورپسې وو. يونتن په فلستيانو حمله وکړه او هغوئ يې ووژل او زلمى هم د هغوئ څۀ کسان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7015, '1 Samuel 14:14', '1 Samuel', 14, 14, '&nbsp;په اوله حمله کښې يونتن او هغه زلمى په يو جريب ځائ کښې تقريباً شل سړى ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7016, '1 Samuel 14:15', '1 Samuel', 14, 15, '&nbsp;نو په هغه ټوله علاقه کښې فلستيان سخت ويرېدل، حمله کوونکى او په خېمو کښې فوجيان د يرې نه ورېږدېدل، زمکه وخوځېدله او هلته يوه لويه وارخطائى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7017, '1 Samuel 14:16', '1 Samuel', 14, 16, '&nbsp;د جبعې د بنيامين په علاقه کښې د ساؤل د محافظانو سړو وليدل چې فلستيانو په پرېشانۍ کښې په هر طرف باندې منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7018, '1 Samuel 14:17', '1 Samuel', 14, 17, '&nbsp;نو ساؤل خپلو سړو ته ووئيل، ”فوجيان وشمېرئ او دا پته ولګوئ چې څوک نشته.“ نو هغوئ شمېر وکړو او پته ورته ولګېده چې يونتن او هغه زلمے نۀ وو چې کوم زلمى به وسله وړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7019, '1 Samuel 14:18', '1 Samuel', 14, 18, '&nbsp;ساؤل اخياه اِمام ته ووئيل، ”پېش بند دلته راوړه.“ په دې ورځ اخياه پېش بند د بنى اِسرائيلو په وړاندې اغوستے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7020, '1 Samuel 14:19', '1 Samuel', 14, 19, '&nbsp;کله چې ساؤل اِمام ته خبرې کولې نو د فلستيانو په قلعه کښې وارخطائى نوره هم زياتېده، نو ساؤل هغۀ ته ووئيل، ”مالِک خُدائ سره د مشورې دپاره وخت نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7021, '1 Samuel 14:20', '1 Samuel', 14, 20, '&nbsp;بيا هغه او د هغۀ سړى د فلستيانو خِلاف جنګ له روان شول، فلستيان دومره په پرېشانۍ کښې وُو چې د يو بل خِلاف جنګېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7022, '1 Samuel 14:21', '1 Samuel', 14, 21, '&nbsp;څۀ عبرانيان کوم چې د فلستيانو په لښکر کښې شامل شوى وُو نو هغوئ بيا راواپس شول او د ساؤل، يونتن او د بنى اِسرائيلو سره شامل شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7023, '1 Samuel 14:22', '1 Samuel', 14, 22, '&nbsp;هغه نور چې د اِفرائيم په غرونو کښې پټ وُو، هغوئ واورېدل چې فلستيان وتښتېدل، نو هغوئ هم د بنى اِسرائيلو سره په جنګ کښې ملګرى شول او په فلستيانو پسې روان شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7024, '1 Samuel 14:23', '1 Samuel', 14, 23, '&nbsp;د بيت‌آون نه اخوا پورې ورسره جنګېدل. مالِک خُدائ په هغه ورځ بنى اِسرائيليان بچ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7025, '1 Samuel 14:24', '1 Samuel', 14, 24, '&nbsp;بنى اِسرائيليان په هغه ورځ د لوږې نه کمزورى شوى وُو، ځکه چې ساؤل قسم سره دا حُکم کړے وو، ”په هغه کس دې لعنت وى چې څوک نن د ماښام نه مخکښې څۀ وخورى چې تر کومې ما د خپلو دشمنانو نه بدل نۀ وى اخستے.“ نو ټوله ورځ د لښکر يو کس هم څۀ ونۀ خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7026, '1 Samuel 14:25', '1 Samuel', 14, 25, '&nbsp;ټول لښکر ځنګل ته دننه شو او په زمکه باندې په هر ځائ کښې د شاتو ګبينونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7027, '1 Samuel 14:26', '1 Samuel', 14, 26, '&nbsp;کله چې هغوئ ځنګل ته وردننه شول، هغوئ وليدل چې شات رابهېدل، خو هيچا هم ونۀ خوړل ځکه چې هغوئ ټول د ساؤل د لعنت نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7028, '1 Samuel 14:27', '1 Samuel', 14, 27, '&nbsp;خو يونتن خبر نۀ وو چې د هغۀ پلار د خلقو نه قسم اخستے دے، نو هغۀ چې کومه امسا ګرځوله هغه يې وروړله، د دې سر يې د شاتو په ګبين کښې ډُوب کړو او لږ يې وخوړل. او هغه سمدستى تازه دم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7029, '1 Samuel 14:28', '1 Samuel', 14, 28, '&nbsp;خو يو سړى ووئيل، ”مونږ ټول د لوږې نه کمزورى يُو، خو ستا پلار زمونږ نه قسم اخستے دے هغۀ وئيلى دى چې نن څوک هم څۀ وخورى نو په هغۀ دې لعنت وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7030, '1 Samuel 14:29', '1 Samuel', 14, 29, '&nbsp;يونتن ورته په جواب کښې ووئيل، ”زما پلار زمونږ د خلقو سره څۀ بد کار کړے دے. ګورئ، ما لږ شات وخوړل او څومره تازه دم شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7031, '1 Samuel 14:30', '1 Samuel', 14, 30, '&nbsp;نن به دا څومره ښۀ وه چې زمونږ خلقو هغه خوراک خوړلے وے چې دشمنانو نه يې د شکست په وخت واخستو. تاسو سوچ وکړئ چې هغوئ به نور څومره فلستيان وژلى وے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7032, '1 Samuel 14:31', '1 Samuel', 14, 31, '&nbsp;په هغه ورځ بنى اِسرائيلو د مِکماس نه تر ايالون پورې فلستيان ووژل او لښکر ډېر سخت ستړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7033, '1 Samuel 14:32', '1 Samuel', 14, 32, '&nbsp;نو هغوئ هغه څيزونو له تېز لاړل چې د دشمن نه يې اخستى وُو، څاروى او د څاروو بچى يې راونيول، هم په هغه ځائ يې حلال کړل او هغه غوښه يې وخوړه چې وينه لا په کښې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7034, '1 Samuel 14:33', '1 Samuel', 14, 33, '&nbsp;ساؤل ته ووئيلے شول، ”ګورئ، خلق د مالِک خُدائ خِلاف ګناه کوى چې هغه غوښه خورى چې وينه لا په کښې ده.“ ساؤل چغه کړه، ”تاسو غدار يئ. دلته يو غټ کاڼے ما له راورغړوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7035, '1 Samuel 14:34', '1 Samuel', 14, 34, '&nbsp;بيا هغۀ يو بل حُکم ورکړو، ”خلقو له ورشئ او ټولو ته ووايئ چې خپل څاروى او ګډې دلته راولى. هغوئ به يې حلال کړى او دلته به يې وخورى، هغوئ دې د مالِک خُدائ خِلاف داسې ګناه نۀ کوى چې هغه غوښه وخورى چې وينه لا په کښې وى.“ نو په هغه شپه هغوئ ټولو خپل څاروى راوستل او هلته يې حلال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7036, '1 Samuel 14:35', '1 Samuel', 14, 35, '&nbsp;ساؤل مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه، دا وړومبۍ قربان‌ګاه وه چې هغۀ جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7037, '1 Samuel 14:36', '1 Samuel', 14, 36, '&nbsp;ساؤل خپلو سړو ته ووئيل، ”راځئ چې لاندې لاړ شُو او په فلستيانو باندې د شپې حمله وکړُو، د سحر پورې به يې لوټ کړُو او يو کس به هم ژوندے پرې نۀ ږدو.“ هغوئ ورته ووئيل، ”څۀ چې تا ته ښۀ ښکارى نو هم هغسې وکړه.“ خو اِمام ووئيل، ”راځئ چې اول د خُدائ پاک نه تپوس وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7038, '1 Samuel 14:37', '1 Samuel', 14, 37, '&nbsp;نو ساؤل د خُدائ پاک نه تپوس وکړو، ”په فلستيانو حمله وکړم څۀ؟ تۀ به مونږ له فتح راکړې؟“ خو خُدائ پاک په هغه ورځ جواب ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7039, '1 Samuel 14:38', '1 Samuel', 14, 38, '&nbsp;بيا ساؤل د خلقو مشرانو ته ووئيل، ”دلته راشئ او دا معلومه کړئ چې نن دا ګناه څنګه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7040, '1 Samuel 14:39', '1 Samuel', 14, 39, '&nbsp;زۀ په ژوندى مالِک خُدائ قسم خورم، څوک چې بنى اِسرائيلو له فتح ورکوى، چې ګناه ګار به ووژلے شى، کۀ هغه زما زوئ يونتن هم وى.“ خو هيچا هيڅ هم ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7041, '1 Samuel 14:40', '1 Samuel', 14, 40, '&nbsp;نو ساؤل هغوئ ته ووئيل، ”تاسو ټول هلته ودرېږئ، زۀ او يونتن به دلته ودرېږو.“ هغوئ جواب ورکړو، ”څۀ چې درته ښۀ ښکارى نو هم هغه وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7042, '1 Samuel 14:41', '1 Samuel', 14, 41, '&nbsp;ساؤل مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ته ووئيل، ”مالِکه خُدايه، تا نن ما له جواب ولې رانۀ کړو؟ مالِکه خُدايه، اے د بنى اِسرائيلو خُدايه پاکه، د دې پاکو کاڼو په ذريعه ما له جواب راکړه. کۀ غلطى زما يا د يونتن وى نو د اُوريم په ذريعه جواب راکړه، خو کۀ دا ستا د خلقو بنى اِسرائيلو غلطى وى نو د تميم په ذريعه جواب راکړه.“ نو جواب يې يونتن او ساؤل وُو او خلق خلاص شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7043, '1 Samuel 14:42', '1 Samuel', 14, 42, '&nbsp;نو ساؤل خلقو ته وفرمائيل، ”زما او زما د زوئ يونتن دپاره پچه واچوئ.“ او پچه د يونتن په نوم راووتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7044, '1 Samuel 14:43', '1 Samuel', 14, 43, '&nbsp;نو ساؤل د يونتن نه تپوس وکړو، ”تا څۀ کړى دى؟“ يونتن ورته وفرمائيل، ”زما سره چې کومه امسا وه د هغې سره مې لږ شان شات خوړلى دى نو زۀ د دې په وجه د مرګ حقدار يم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7045, '1 Samuel 14:44', '1 Samuel', 14, 44, '&nbsp;ساؤل هغۀ ته وفرمائيل، ”کۀ تۀ ونۀ وژلے شوې نو خُدائ پاک دې ما ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7046, '1 Samuel 14:45', '1 Samuel', 14, 45, '&nbsp;خو خلقو ساؤل ته ووئيل، ”يونتن به وژلے شى څۀ، چا چې د بنى اِسرائيلو دپاره لويه فتح موندلې ده؟ نه، مونږ په ژوندى مالِک خُدائ قسم خورو چې هغه به د هغۀ يو وېښتۀ هم په زمکه باندې ونۀ غورزوى. هغۀ چې نن څۀ کړى دى هغه يې د خُدائ پاک په مدد سره کړى دى.“ نو خلقو يونتن د مرګ نه بچ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7047, '1 Samuel 14:46', '1 Samuel', 14, 46, '&nbsp;د هغې نه پس، ساؤل په فلستيانو پسې نور لا نۀ ړو او هغوئ خپلې علاقې ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7048, '1 Samuel 14:47', '1 Samuel', 14, 47, '&nbsp;کله چې ساؤل د بنى اِسرائيلو بادشاه شو، نو هغۀ د خپلو ټولو دشمنانو سره په هر ځائ کښې جنګ کولو يعنې د موآب خلقو، عمونيانو، ادوميانو، د ضوباه بادشاهانو او فلستيانو سره. هغۀ چې چرته هم جنګ کولو نو هغه کاميابېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7049, '1 Samuel 14:48', '1 Samuel', 14, 48, '&nbsp;هغۀ په بهادرۍ سره جنګ وکړو او عماليقيانو له يې هم شکست ورکړو. هغۀ بنى اِسرائيليان د دشمن د ټولو حملو نه بچ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7050, '1 Samuel 14:49', '1 Samuel', 14, 49, '&nbsp;يونتن، اِسوى او مُلکى‌شوَع د ساؤل زامن وُو. د هغۀ د مشرې لور ميرب او د کشرې ميکل نوم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7051, '1 Samuel 14:50', '1 Samuel', 14, 50, '&nbsp;د هغۀ ښځه اخينوعم د اخيمعض لور وه، د هغۀ د لښکر مشر د هغۀ د ترۀ نير زوئ ابنير وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7052, '1 Samuel 14:51', '1 Samuel', 14, 51, '&nbsp;د ساؤل پلار قيس او د ابنير پلار نير د ابى‌اېل زامن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7053, '1 Samuel 14:52', '1 Samuel', 14, 52, '&nbsp;چې تر کومې پورې هغه ژوندے وو، نو هغۀ به د فلستيانو خِلاف ډېر سخت جنګونه کول. نو چې کله هم هغۀ ته يو سړے مِلاوېدو چې مضبوط يا تکړه وو، نو هغۀ به هغه په خپل لښکر کښې شاملولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7054, '1 Samuel 15:1', '1 Samuel', 15, 1, '&nbsp;سموئيل ساؤل ته وفرمائيل، ”مالِک خُدائ زۀ رالېږلے يم چې تا د هغۀ د خلقو بنى اِسرائيلو بادشاه جوړ کړم. نو د مالِک خُدائ کلام ته غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7055, '1 Samuel 15:2', '1 Samuel', 15, 2, '&nbsp;دا هغه څۀ دى چې ربُ الافواج يې فرمائى، چې زۀ به عماليقيانو له سزا ورکړم ځکه چې بنى اِسرائيليان چې کله د مِصر نه راتلل نو هغوئ ورته لاره نيولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7056, '1 Samuel 15:3', '1 Samuel', 15, 3, '&nbsp;اوس لاړ شئ او په عماليقيانو حمله وکړئ او د هغوئ هر څۀ بېخى تباه کړئ. يو څيز هم مۀ پرېږدئ، سړى، ښځې، ماشومان او هغه ماشومان چې تے روى ووژنئ، څاروى، ګډې، اوښان او خرۀ هر څۀ ووژنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7057, '1 Samuel 15:4', '1 Samuel', 15, 4, '&nbsp;بيا ساؤل خپل لښکر راغونډ کړو او په طلائم کښې يې وشمېرلو. دوه لاکه بنى اِسرائيل فوجيان وُو او لس زره د يهوداه قبيلې فوجيان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7058, '1 Samuel 15:5', '1 Samuel', 15, 5, '&nbsp;بيا هغه او د هغۀ سړى عماليقى ښار ته لاړل او په يو وادۍ کښې يې ورته لاره ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7059, '1 Samuel 15:6', '1 Samuel', 15, 6, '&nbsp;هغۀ قينيانو له خبردارے ولېږلو چې، ”د عماليقيانو نه لاړ شئ نو چې داسې زۀ تاسو د هغوئ سره نۀ تباه کوم، ځکه چې تاسو په هغه وخت کښې په ټولو بنى اِسرائيلو باندې مِهربانه شوئ کله چې هغوئ د مِصر نه راوتل.“ نو قينيان د عماليقيانو نه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7060, '1 Samuel 15:7', '1 Samuel', 15, 7, '&nbsp;ساؤل عماليقيانو له شکست ورکړو، د مِصر نمرخاتۀ طرف ته، د حويله نه تر شور پورې ورسره وجنګېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7061, '1 Samuel 15:8', '1 Samuel', 15, 8, '&nbsp;هغۀ د عماليقيانو بادشاه اجاج ژوندے ونيولو او ټول خلق يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7062, '1 Samuel 15:9', '1 Samuel', 15, 9, '&nbsp;خو ساؤل او د هغۀ سړو د اجاج ژوند بچ کړو او ښې ګډې، څاروى او څورب سخى او ګډُورى يې ونۀ وژل او داسې نور ښۀ څيزونه يې هم تباه نۀ کړل، هغوئ صِرف هغه څيزونه تباه کړل چې کمزورى او بې‌کاره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7063, '1 Samuel 15:10', '1 Samuel', 15, 10, '&nbsp;بيا د مالِک خُدائ پېغام سموئيل ته راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7064, '1 Samuel 15:11', '1 Samuel', 15, 11, '&nbsp;”زۀ پښېمانه يم چې ما ساؤل بادشاه جوړ کړو، هغه زما نه اوړېدلے دے او زما حُکمونه يې نۀ دى منلى.“ سموئيل خفه وو او ټوله شپه يې مالِک خُدائ ته سوال زارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7065, '1 Samuel 15:12', '1 Samuel', 15, 12, '&nbsp;په ورپسې سحر وختى هغه د ساؤل لټولو له لاړو. هغه خبر شو چې ساؤل د کرمل ښار ته تلے وو، چرته چې هغۀ د ځان دپاره يادګارى ستنه جوړه کړه او بيا جِلجال ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7066, '1 Samuel 15:13', '1 Samuel', 15, 13, '&nbsp;سموئيل ساؤل له لاړو، ساؤل ورته په خېر راغلے ووئيل او ورته يې ووئيل، ”سموئيله، مالِک خُدائ دې تا له برکت درکړى. ما د مالِک خُدائ حُکم منلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7067, '1 Samuel 15:14', '1 Samuel', 15, 14, '&nbsp;سموئيل ترې نه تپوس وکړو، ”نو زۀ ولې د څاروو او ګډو رمباړى اورم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7068, '1 Samuel 15:15', '1 Samuel', 15, 15, '&nbsp;ساؤل جواب ورکړو، ”زما سړو دا د عماليقيانو نه اخستى دى. هغوئ ښې ګډې او څاروى ساتلى دى چې مالِک خُدائ ستاسو خُدائ پاک ته يې د نذرانې په توګه پېش کړى. او باقى ټول مو بېخى تباه کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7069, '1 Samuel 15:16', '1 Samuel', 15, 16, '&nbsp;سموئيل حُکم وکړو، ”غلى شئ او غوږ ونيسئ نو زۀ به تاسو ته ووايم چې تېره شپه ما ته مالِک خُدائ څۀ فرمائيلى دى.“ ساؤل ورته ووئيل، ”ما ته ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7070, '1 Samuel 15:17', '1 Samuel', 15, 17, '&nbsp;سموئيل جواب ورکړو، ”اګر چې تا په خپله هم يو ځل خپل ځان وړوکے ګڼلو، خو اوس تۀ د بنى اِسرائيلو د قبيلو مشر يې. مالِک خُدائ تۀ د بنى اِسرائيلو د بادشاه په توګه مقرر کړې يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7071, '1 Samuel 15:18', '1 Samuel', 15, 18, '&nbsp;او هغۀ تۀ د دې حُکم سره دې مقصد دپاره لېږلے وې چې د عماليقيانو ګناه ګار خلق تباه کړې. هغۀ تا ته ووئيل چې تر هغې پورې ورسره جنګ وکړه چې ټول ووژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7072, '1 Samuel 15:19', '1 Samuel', 15, 19, '&nbsp;نو بيا تا د هغۀ فرمانبردارى ولې ونۀ وکړه؟ تا په مالِ غنيمت نيولو کښې تېزى ولې وکړه؟ او د مالِک خُدائ په نظر کښې داسې بد عمل دې ولې وکړو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7073, '1 Samuel 15:20', '1 Samuel', 15, 20, '&nbsp;ساؤل جواب ورکړو، ”خو ما د مالِک خُدائ فرمانبردارى کړې ده. زۀ لاړم لکه څنګه چې هغۀ راته فرمائيلى وُو، اجاج بادشاه مې واپس راوستلو او ټول عماليقيان مې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7074, '1 Samuel 15:21', '1 Samuel', 15, 21, '&nbsp;خو زما سړو چې کومې ښې ګډې او څاروى نيولى وُو هغه يې ونۀ وژل، په ځائ د دې يې هغه دلته جِلجال ته راوستل چې مالِک خُدائ ستاسو خُدائ پاک ته يې د نذرانې په توګه پېش کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7075, '1 Samuel 15:22', '1 Samuel', 15, 22, '&nbsp;سموئيل ورته وفرمائيل، ”مالِک خُدائ په سوزېدونکو نذرانو او قربانو باندې زيات خوشحاليږى او يا کۀ د هغۀ په خبره منلو باندې خوشحاليږى؟ بې‌شکه، تابعدارى د قربانۍ نه بهتره ده او د هغۀ په خبره عمل کول د ګډانو د وازګې د نذرانې نه بهتر دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7076, '1 Samuel 15:23', '1 Samuel', 15, 23, '&nbsp;د هغۀ خِلاف سرکشى د تور جادو په شان خراب کار دے او غرور د بُت پرستۍ هومره ګناه لرى. تا د هغۀ حُکم نامنظوره کړو نو ځکه هغۀ تۀ د بادشاه په توګه نامنظوره کړې يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7077, '1 Samuel 15:24', '1 Samuel', 15, 24, '&nbsp;ساؤل جواب ورکړو، ”آو، ما ګناه کړې ده. ما د مالِک خُدائ د حُکم او ستا د لارښودنو نافرمانى کړې ده. زۀ د خپلو سړو نه يرېدم او چې هغوئ څۀ غوښتل نو ما يې خبره منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7078, '1 Samuel 15:25', '1 Samuel', 15, 25, '&nbsp;خو اوس زۀ تا ته سوال کوم چې زما ګناه وبخښه او واپس زما سره لاړ شه، نو چې داسې زۀ د مالِک خُدائ عبادت وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7079, '1 Samuel 15:26', '1 Samuel', 15, 26, '&nbsp;سموئيل جواب ورکړو، ”زۀ به تا سره واپس نۀ ځم. تا د مالِک خُدائ حُکم نامنظوره کړے دے او تۀ هغۀ په بنى اِسرائيلو د بادشاه په توګه نامنظوره کړے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7080, '1 Samuel 15:27', '1 Samuel', 15, 27, '&nbsp;نو سموئيل د تلو دپاره راوګرځېدو، خو ساؤل هغه د چُوغې نه ونيولو او چُوغه وشلېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7081, '1 Samuel 15:28', '1 Samuel', 15, 28, '&nbsp;سموئيل هغۀ ته وفرمائيل، ”مالِک خُدائ نن ستا نه د بنى اِسرائيلو بادشاهى لرې کړې ده او هغه چا له يې ورکړې ده چې هغه ستا نه ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7082, '1 Samuel 15:29', '1 Samuel', 15, 29, '&nbsp;د بنى اِسرائيلو خُدائ تعالىٰ نۀ دروغ وائى او نۀ خپله فېصله بدلوى. هغه د انسان په شان نۀ دے، هغه خپله فېصله نۀ بدلوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7083, '1 Samuel 15:30', '1 Samuel', 15, 30, '&nbsp;ساؤل جواب ورکړو، ”ما ګناه کړې ده. خو کم از کم زما د خپلو خلقو د مشرانو او بنى اِسرائيلو په مخکښې زما عزت وکړه. ما سره واپس لاړ شه نو چې زۀ د مالِک خُدائ ستاسو د خُدائ پاک عبادت وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7084, '1 Samuel 15:31', '1 Samuel', 15, 31, '&nbsp;نو سموئيل د هغۀ سره واپس لاړو او ساؤل د مالِک خُدائ عبادت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7085, '1 Samuel 15:32', '1 Samuel', 15, 32, '&nbsp;سموئيل حُکم وکړو، ”د عماليقيانو بادشاه اجاج ما له دلته راولئ.“ اجاج هغۀ له ښۀ زړَور راغلو، خيال يې دا وو چې بچ به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7086, '1 Samuel 15:33', '1 Samuel', 15, 33, '&nbsp;سموئيل ورته وفرمائيل، ”څنګه چې ستا تُورې ډېرې ميندې بې‌اولاده کړى دى، نو اوس به ستا مور هم بې‌اولاده شى.“ او هغۀ اجاج په جِلجال کښې د مالِک خُدائ قربان‌ګاه په مخکښې ټوټې ټوټې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7087, '1 Samuel 15:34', '1 Samuel', 15, 34, '&nbsp;بيا سموئيل راما ته لاړو او ساؤل بادشاه په جبعه کښې خپل کور ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7088, '1 Samuel 15:35', '1 Samuel', 15, 35, '&nbsp;چې ترڅو پورې سموئيل ژوندے وو، نو هغۀ بيا هيڅکله ساؤل ونۀ ليدو، خو سموئيل ورباندې غمژن وو. مالِک خُدائ په دې پښېمانه وو چې ساؤل يې په بنى اِسرائيلو باندې بادشاه جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7089, '1 Samuel 16:1', '1 Samuel', 16, 1, '&nbsp;بيا مالِک خُدائ سموئيل ته وفرمائيل، ”تۀ به تر کومې پورې په ساؤل پسې خفګان کوې؟ هغه ما په بنى اِسرائيلو باندې د بادشاهۍ دپاره نامنظوره کړے دے. نو د زيتُونو لږ تېل واخله او بيت‌لحم ته لاړ شه هغه سړى له چې نوم يې يَسى دے، ځکه چې ما د هغۀ د زامنو نه يو کس خوښ کړے دے چې بادشاه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7090, '1 Samuel 16:2', '1 Samuel', 16, 2, '&nbsp;سموئيل ترې نه تپوس وکړو، ”دا زۀ څنګه وکړم؟ کۀ ساؤل د دې نه خبر شى نو هغه به ما ووژنى.“ مالِک خُدائ ورته وفرمائيل، ”تۀ د ځان سره يوه سخۍ بوځه او هلته ووايه چې تۀ هلته ځکه يې چې مالِک خُدائ ته يوه قربانى پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7091, '1 Samuel 16:3', '1 Samuel', 16, 3, '&nbsp;يَسى قربانۍ له راوغواړه او زۀ به تا ته ووايم چې څۀ به کوې. زۀ چې کوم سړے درته ښايم نو د نښې په طور به تۀ د هغۀ سر په تېلو غوړ کړې چې بادشاه جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7092, '1 Samuel 16:4', '1 Samuel', 16, 4, '&nbsp;سموئيل هم هغه شان وکړل چې څۀ ورته مالِک خُدائ فرمائيلى وُو او بيت‌لحم ته لاړو، هلته د ښار مشران په يره يره کښې د هغۀ سره مِلاوېدو دپاره راغلل او تپوس يې ترې نه وکړو، ”د امن په نيت راغلے يې کۀ نه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7093, '1 Samuel 16:5', '1 Samuel', 16, 5, '&nbsp;هغۀ ورته وفرمائيل، ”آو، د امن په نيت راغلم، زۀ راغلم چې مالِک خُدائ ته يوه قربانى پېش کړم. ځان پاک کړئ او ما سره لاړ شئ.“ هغۀ يَسى او د هغۀ زامنو ته هم وفرمائيل چې ځان پاک کړئ او هغوئ يې قربانۍ له راوغوښتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7094, '1 Samuel 16:6', '1 Samuel', 16, 6, '&nbsp;کله چې هغوئ ورسېدل، سموئيل د يَسى زوئ اِلياب وليدو او خپل ځان سره يې ووئيل، ”دا سړے کوم چې دلته د مالِک خُدائ په حضور کښې ولاړ دے دا بې‌شکه هم هغه دے چې کوم مالِک خُدائ خوښ کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7095, '1 Samuel 16:7', '1 Samuel', 16, 7, '&nbsp;خو مالِک خُدائ هغۀ ته وفرمائيل، ”هغه ما نامنظوره کړے دے نو تۀ دې ته مۀ ګوره چې هغه څومره لوړ دے او مۀ يې ظاهر ته ګوره. ځکه چې مالِک خُدائ د انسان په شان چا ته نۀ ګورى. انسان ظاهر ته ګورى او مالِک خُدائ زړۀ ته ګورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7096, '1 Samuel 16:8', '1 Samuel', 16, 8, '&nbsp;يَسى خپل زوئ ابينداب راوغوښتو او سموئيل له يې راوستلو. خو سموئيل ورته وفرمائيل، ”نه، مالِک خُدائ دا هم نۀ دے خوښ کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7097, '1 Samuel 16:9', '1 Samuel', 16, 9, '&nbsp;يَسى بيا سِمعه راوستلو. نو سموئيل وفرمائيل، ”مالِک خُدائ دے هم نۀ دے خوښ کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7098, '1 Samuel 16:10', '1 Samuel', 16, 10, '&nbsp;داسې يَسى اووۀ زامن سموئيل له راوستل. او سموئيل هغۀ ته وفرمائيل، ”نه، مالِک خُدائ دا يو هم نۀ دے خوښ کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7099, '1 Samuel 16:11', '1 Samuel', 16, 11, '&nbsp;هغۀ ترې نه بيا تپوس وکړو، ”ستا نور زامن شته څۀ؟“ يَسى ورته ووئيل، ”د ټولو نه کشر پاتې دے، خو هغه بهر د ګډو خيال ساتى.“ سموئيل ورته وفرمائيل، ”هغه راوغواړه چې دلته راشى. مونږ به تر هغې قربانى نه پېش کوُو چې هغه راغلے نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7100, '1 Samuel 16:12', '1 Samuel', 16, 12, '&nbsp;نو يَسى هغه راوغوښتو. هغه يو ښائسته او سور سپين زلمے وو او ښائسته سترګې يې لرلې. مالِک خُدائ سموئيل ته وفرمائيل، ”هم دغه يو دے، سر يې په تېلو غوړ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');